const images = $input.all()[0].json.images;
const userEmail = $input.all()[0].json.email;
const ctaClicked = $input.all()[0].json.ctaClicked;

if (!ctaClicked) {
  throw new Error('CTA non cliqué');
}

if (!images || images.length === 0) {
  throw new Error('Aucune image fournie');
}

if (!userEmail || !userEmail.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
  throw new Error('Email invalide');
}

const validImages = images.filter(img => img.source === 'cta_upload');

return validImages.map((img, index) => ({
  json: {
    imageData: img.data,
    imageUrl: img.url,
    imageName: img.name || `image_${index + 1}`,
    userEmail: userEmail,
    timestamp: new Date().toISOString()
  }
}));

// Parse la réponse Ollama
const aiResponse = JSON.parse($json.response);

const laozahangPrompt = `Professional advertising image, high quality, commercial photography style.

Original concept: ${aiResponse.visualConcept}

${aiResponse.laozahangPrompt}

Style: ${aiResponse.adTheme}, ${aiResponse.colorPalette}
Mood: engaging, eye-catching, professional
Quality: 8K, ultra detailed, commercial grade
Composition: rule of thirds, balanced

Negative prompt: low quality, blurry, amateur, cluttered`;

return [{
  json: {
    originalImage: $input.first().json.imageData,
    userEmail: $input.first().json.userEmail,
    adConcept: aiResponse,
    laozahangPrompt: laozahangPrompt,
    tagline: aiResponse.tagline
  }
}];

const generatedImages = $json.images || [];
const emailData = $input.first().json;

const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }
    .content { background: #f9f9f9; padding: 30px; border-radius: 0 0 10px 10px; }
    .tagline { font-size: 24px; font-weight: bold; color: #667eea; margin: 20px 0; text-align: center; }
    .concept { background: white; padding: 20px; margin: 20px 0; border-radius: 8px; }
    .image-grid { display: grid; gap: 15px; margin: 20px 0; }
    .image-grid img { width: 100%; border-radius: 8px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🎨 Vos Publicités Sont Prêtes !</h1>
    <p>Généré automatiquement par IA</p>
  </div>
  <div class="content">
    <div class="tagline">"${emailData.tagline}"</div>
    <div class="concept">
      <h2>💡 Concept Publicitaire</h2>
      <p><strong>Thème:</strong> ${emailData.adConcept.adTheme}</p>
      <p><strong>Concept:</strong> ${emailData.adConcept.visualConcept}</p>
      <p><strong>Couleurs:</strong> ${emailData.adConcept.colorPalette}</p>
    </div>
    <h2>🖼️ Images Générées</h2>
    <div class="image-grid">
      ${generatedImages.map((img, i) => `<img src="${img.url}" alt="Pub ${i + 1}" />`).join('')}
    </div>
    <p style="text-align: center; color: #666; margin-top: 30px;">Ces images sont prêtes pour vos campagnes !</p>
  </div>
</body>
</html>
`;

return [{
  json: {
    to: emailData.userEmail,
    subject: `✨ Vos ${generatedImages.length} publicités IA sont prêtes !`,
    html: emailHtml
  }
}];
